	["Armas para grupo"] = "組隊武器",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "專為地城設計的武器配點：用橫掃攻擊對多個敵人造成大量傷害，用致死打擊對付首領，並提高命中避免失手。",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "以不死為優先的武器配點：招架更多攻擊、讓逃跑的敵人減速，最後點一些防護以降低受到的傷害。",
	["Armas seguro"] = "穩健武器",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "武器、護甲、材料、配方與坐騎：誰掉落、誰販售。",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "把每個戰鬥框架拖到適合的位置。完成後鎖定，以免礙事。",
	["Arrastra otra bolsa aquí para cambiarla."] = "將另一個背包拖到這裡即可替換。",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "拖曳即可移動框架。大小與欄數請在「治療」頁面調整。",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "拖曳以移動框架。點擊（可搭配 Shift、Ctrl 或 Alt）查看會施放什麼。",
	["Arrastra una bolsa aquí para ponerla."] = "將背包拖到這裡即可裝備。",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "視窗頂部顯示每個已裝備的背包及其空間：滑鼠移到上面可標示其中的物品，拖入另一個背包即可替換。",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "上方是 Alfa 的推薦。點一下就能開始。",
