	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "強力的雷霆一擊：把好幾隻怪聚在一起並讓它們全部減速。",
	["Atronar más barato para agarrar varios."] = "更便宜的雷霆一擊，用來穩住好幾隻怪。",
