	["Atrás"] = "返回",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "他會用錘子擊昏坦克：讓坦克的生命值保持在高檔。",
	["Aturdes a uno mientras peleas con otro."] = "一邊打一個，一邊擊昏另一個。",
