	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "點擊其中一個：Alfa 地圖會移到它那裡。「跟隨」會設定箭頭與路線。",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "點擊其中一個：Alfa 地圖會移到它那裡。「跟隨」會設定箭頭與路線；狼群爪印會把它分享給使用 Alfa 的人。",
