	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "複製下方的字串，透過聊天或 Discord 傳給別人：對方用 Alfa 在「匯入」貼上，就能得到和你一樣的配點。",
	["Copia tu mapa al clic para lanzar de Blizzard, así curas igual en sus marcos de grupo. Si el juego no lo deja, abre su ventana para que lo hagas ahí."] = "將你的點擊配置複製到 Blizzard 的點擊施法，讓你在其隊伍框架上也能用同樣方式治療。如果遊戲不允許，會開啟其視窗讓你在那裡設定。",
