	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "當你攜帶物品時，Alfa 會告訴你該賣給商人、拍賣還是加工，以及能賺多少。",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "當其他使用 Alfa 的狼分享位置時，會出現在這裡與你的地圖上。想讓狼群壯大，就邀請你的朋友：安裝 Alfa、同意分享並加入 La Jauría 的 Discord。",
	["Cuando se llenan"] = "背包滿時",
