	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "拍賣場視窗下方的「用 Alfa 掃描」按鈕。",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "核心的查詢已關閉（設定 > 探索）：請開啟，讓 Alfa 能建立指南。",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "在世界地圖與小地圖上顯示通往目標的路線：步行處為線條或圓點，飛行、航行或搭乘處為線條，之後的路段較淡。",
	["El camino hasta el destino dibujado en el mapa."] = "在地圖上畫出前往目的地的路徑。",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "最簡單的練等方式：一把大武器、造成流血的攻擊，以及等級 40 的致死打擊。耐打又殺得快。",
	["El clan"] = "公會介紹",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "單純按右鍵仍然會像往常一樣縮小遊戲地圖。",
	["El clic izquierdo solo selecciona"] = "左鍵只用來選取目標",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "經典的 PvP 配點：致死打擊降低對手受到的治療，強化斷筋讓他無法動彈，強化衝鋒讓你一開場就有怒氣。",
	["El color de mi clase"] = "我的職業顏色",
	["El comerciante no lo compra"] = "商人不收購",
	["El corcho está en el agua. Cuando se hunda, haz clic derecho sobre él para recoger."] = "浮標已在水中。當它沉下去時，右鍵點擊浮標即可收竿。",
	["El corcho está en el agua. Cuando se hunda, pulsa %s para recoger."] = "浮標已在水中。當它沉下去時，按 %s 收竿。",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "滑鼠指向時顯示玩家的滑鼠提示。戰鬥中不顯示，以免礙事。",
	["El daño por segundo de tu arma a distancia."] = "你的遠程武器的每秒傷害。",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "武器的每秒傷害：對戰士來說，這是練等時最重要的。",
	["El destino de la flecha y sus zonas en el minimapa."] = "在小地圖上顯示箭頭的目的地與其區域。",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "在地圖上顯示箭頭的目的地、路徑與此步驟的其他目標。",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "核心的地城導覽手冊已關閉（設定 > 探索 > 地城）。",
	["El diario de mazmorras está apagado"] = "地城導覽手冊已關閉",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "敵人閃躲了：壓制無法被閃躲，而且傷害很高。",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "敵人閃躲了：這個近戰攻擊已可使用。",
	["El enemigo esquivó: este golpe está listo."] = "敵人閃躲了：這個攻擊已就緒。",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "敵人貼身了：用近戰攻擊它。",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "精神讓你快速回復法力：幾乎不用休息。",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "火焰會打到附近所有人：讓近戰隊友的生命值保持在高檔。",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "地城中傷害最高的戰士。有坦克在前面時，你的雙武器停不下來，強化斬殺負責收掉首領。",
	["El izquierdo selecciona y el derecho abre el menú."] = "左鍵選取目標，右鍵開啟選單。",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "左鍵選取目標，右鍵開啟選單。其餘由你決定。",
	["El izquierdo selecciona y el derecho abre el menú; tu clase no tiene buffs para otros."] = "左鍵選取目標，右鍵開啟選單；你的職業沒有可以給別人的增益效果。",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "遊戲會依情況在這些技能中選擇；圖示會顯示現在最適合的那個。",
	["El juego la hizo brillar: es buen momento para usarla."] = "遊戲讓它發光了：現在正是使用的好時機。",
	["El juego no aceptó esa tecla."] = "遊戲不接受這個按鍵。",
	["El juego no aceptó la prueba."] = "遊戲不接受這次測試。",
	["El juego no deja cambiar talentos ahora mismo"] = "遊戲目前不允許變更天賦",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "遊戲現在不允許傳送訊息（首領戰或比賽中）。結束後你的蹤跡會自動恢復傳送。",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "遊戲不允許試玩帳號傳送插件訊息或使用自訂頻道。你的隊伍仍然看得到。",
	["El juego no dejó cambiar las demás."] = "遊戲不允許變更其餘選項。",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "遊戲現在不允許分享標記。請稍後再試。",
	["El juego no dejó comprar ese rango."] = "遊戲不允許點這一級。",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "遊戲不允許進入 Alfa 的隱藏頻道，而沒有公會就沒有其他分享方式。Alfa 會在幾分鐘後自動重試。你的隊伍仍然看得到。",
	["El juego no la ofrece ahora mismo."] = "遊戲現在沒有提供它。",
	["El juego no lo dice ahora."] = "遊戲目前沒有提供這項資訊。",
	["El juego no permite usar el medidor ahora."] = "遊戲現在不允許使用傷害統計。",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "遊戲沒有 Blizzard 的戰鬥輔助，所以 Alfa 依它為%s制定的優先順序給出建議，只讀取你的角色：你的資源、你身上的效果以及遊戲允許你使用的技能。3 個以上敵人時會改用範圍技能。按什麼由你決定。",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "戰鬥中遊戲會隱藏精確數字：可以看到計量條與數值，詳細資訊在脫離戰鬥後顯示。",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "遊戲拒絕確認變更。已復原，讓你的天賦樹維持原狀。",
	["El juego todavía no carga tu árbol"] = "遊戲還沒載入你的天賦樹",
	["El juego todavía no carga tu árbol."] = "遊戲還沒載入你的天賦樹。",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "遊戲還沒載入你的天賦。請稍等幾秒，或開啟一次天賦視窗（N 鍵）。",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "遊戲還沒有某些物品的資料。稍後就會顯示。",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "遊戲仍在隱藏數字或名稱（戰鬥中與地城內會這樣）。離開後再試。",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "傷害最高的法師：火焰法術與會造成灼燒的致命一擊。",
	["El mapa a tu gusto"] = "隨心打造地圖",
	["El mapa de Alfa"] = "Alfa 地圖",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Alfa 地圖、遊戲地圖與小地圖。如果有什麼礙事，就在這裡關閉；Alfa 的其他模組也會把它們的圖層加入這個清單。",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "可縮放的整個世界地圖、你的標記，以及統一控制地圖上所有內容的開關。",
	["El mapa no se abre en combate."] = "戰鬥中無法開啟地圖。",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "地圖與小地圖上每個標記下方的徽章：Alfa 的樣式，或只顯示圖形、不帶徽章。",
	["El medidor no está disponible"] = "傷害統計無法使用",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "遊戲地圖的放大鏡選單中也會列出所有 Alfa 圖層。",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "小地圖由圓形改為方形，並加上細邊框。不建議與「旋轉小地圖」一起使用。",
	["El modelo no lleva nada aquí."] = "模型這個欄位沒有裝備。",
	["El modo prueba se usa fuera de combate."] = "測試模式只能在戰鬥外使用。",
	["El motor no aceptó la guía."] = "核心不接受這個指南。",
	["El motor no puede armar guías ahora."] = "核心現在無法建立指南。",
	["El mundo entero en un mapa"] = "整個世界盡在一張地圖",
	["El módulo Curación no está cargado."] = "「治療」模組未載入。",
	["El nombre de cada zona sobre el mapa de Alfa."] = "在 Alfa 地圖上顯示各地區的名稱。",
	["El número abajo a la izquierda de cada pieza de equipo."] = "每件裝備左下角的數字。",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "數字是點天賦的順序。滑鼠移到天賦上可查看效果。",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "目前步驟使用的物品，或它要收集的任務物品，會在你的背包中發光。之後步驟需要的物品會加上鎖頭，讓你不會賣掉它。",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "順序比數字更重要：找有清單前幾項屬性的裝備。",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Alfa 的資料包（Alfa_Codex）已停用：請在插件清單中啟用並重新載入。",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "最容易練等的盜賊：可以正面攻擊、閃躲很多，也比其他配點耐打。",
	["El rango de niveles de cada zona, con color según tu nivel."] = "各地區的等級範圍，依你的等級著色。",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "追蹤器會告訴你下一步，箭頭會帶你過去。",
	["El registro de daño del juego está apagado"] = "遊戲的傷害記錄已關閉",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "遊戲的傷害記錄已關閉：開啟後即可查看你隊伍的排行。",
	["El reino limita los mensajes de addon salientes: %s"] = "伺服器限制了發出的插件訊息：%s",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "薩滿的治療專精：鏈狀治療與幫助整個隊伍的圖騰。",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "德魯伊的治療專精：能治療任何隊伍且很能活，不過單練時殺怪較慢。",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "聖騎士的治療專精：強力的治療與厚重的護甲，非常適合組隊。",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "純粹的治療者：大量治療，以及給整個隊伍的治療。",
	["El sistema de equipo de Alfa no está disponible."] = "無法使用 Alfa 的裝備系統。",
	["El talento que toca"] = "該點的天賦",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "經典的坦克：大量格擋，用復仇與盾牌猛擊產生仇恨，情況失控時還有破釜沉舟。",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "最難被打死的坦克：點滿所有防禦天賦、強化盾牆，並及早點出破釜沉舟。非常適合剛開始當坦克的人。",
	["El texto es demasiado largo."] = "文字太長了。",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "文字不完整或被更改：請重新複製。",
	["El tipo de nodos que une la ruta."] = "路線要串連的採集點類型。",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "背景的色調：石墨是 Alfa 的預設色調，夜晚最暗，石板為中性灰。",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "在一個小視窗中顯示你隊伍或團隊的 DPS 排行，包括目前與上一場戰鬥。",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Alfa 的路線樹、陸續解鎖的任務，以及物品目錄。",
	["El último punto: paras un poco más."] = "最後一點：招架稍微再多一些。",
	["Elegido"] = "已選擇",
	["Elegido por ti"] = "你自選的",
	["Elegir capas"] = "選擇圖層",
	["Elegir la siguiente guía"] = "選擇下一個指南",
	["Elegir mi camino"] = "選擇我的方向",
	["Elegir mi primera guía"] = "選擇我的第一個指南",
	["Elegir mi tecla"] = "選擇我的按鍵",
	["Elegir otra guía"] = "選擇其他指南",
	["Elegir qué sigue"] = "選擇接下來做什麼",
	["Elegir una guía"] = "選擇指南",
	["Elemental"] = "元素",
	["Elemental para subir"] = "元素（練等）",
	["Elfos de la noche"] = "夜精靈",
	["Elige algo de la lista"] = "從清單中選擇一項",
	["Elige el objeto"] = "選擇物品",
	["Elige el objeto en la Enciclopedia."] = "在百科中選擇物品。",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "選擇要存放的東西：銀行裡已有的物品、材料、某個分類，或所有非裝備物品。脫離戰鬥時一次移動。",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "選擇你想做的事，Alfa 會一步步帶你。",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "選擇地圖上顯示的內容：指南、任務、稀有、旅行、地區以及其他模組加入的內容。",
	["Elige solo misiones que ya puedes tomar."] = "只選擇你現在就能接的任務。",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "選擇你的方向。如果不確定，就從練等開始：Alfa 會告訴你怎麼做最划算。",
	["Elige tu estilo"] = "選擇你的風格",
	["Elige tu tecla para pescar"] = "選擇你的釣魚按鍵",
	["Elige tus clics"] = "選擇你的點擊",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "選擇你的點擊、擺放框架並測試。只需一分鐘。",
	["Elige tú la zona."] = "由你選擇地區。",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "選擇一條路線：Alfa 會制定你的計畫並一步步帶你。",
	["Elige una guía para empezar"] = "選擇一個指南開始",
	["Elige uno y lo ves al instante en todas las ventanas de Alfa, también la flecha."] = "選一個，所有 Alfa 視窗（包括箭頭）都會立即套用。",
	["Eliges una"] = "任選一個",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "她會催眠整個隊伍，然後復活莫格萊尼：這是正常的，別慌。",
	["Embate con escudo: mucho daño y amenaza."] = "盾牌猛擊：高傷害與高仇恨。",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "猛擊不再重置你的攻擊計時：在兩次攻擊之間多打一下。",
	["Embate sin perder tu ataque automático."] = "使用猛擊而不損失自動攻擊。",
	["Embate sin perder tu ataque."] = "使用猛擊而不損失攻擊。",
	["Embate sin perder tu golpe automático."] = "使用猛擊而不損失自動攻擊。",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "使用猛擊而不重置攻擊計時：多打一下。",
	["Embate: un golpe fuerte entre golpe y golpe."] = "猛擊：在兩次攻擊之間打出一記重擊。",
	["Empezar"] = "開始",
	["Empezar de cero"] = "從頭開始",
	["Empezar de nuevo"] = "重新開始",
	["Empezó %s"] = "開始於%s",
	["Empezó %s."] = "開始於%s。",
	["Empieza al usar este objeto"] = "使用此物品後開始",
	["Empieza aquí"] = "從這裡開始",
	["Empieza con %s, que se consigue en la mazmorra."] = "從%s開始，可在地城中取得。",
	["Empieza con %s, que suelta %s."] = "從%s開始，由%s掉落。",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "從遠處用你施法最慢的法術開場，再用瞬發法術收尾。",
	["Empieza dentro"] = "在副本內開始",
	["Empieza una misión"] = "開始一個任務",
	["Empiezas: nivel %d"] = "起始：%d 級",
	["En 9 idiomas"] = "支援 9 種語言",
	["En camino"] = "前往中",
	["En combate"] = "戰鬥中",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "戰鬥中遊戲會隱藏精確數字：計量條與數值照常顯示，詳細資訊與通報在脫離戰鬥後才能使用。",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "戰鬥中無法從 Alfa 開啟遊戲地圖：請使用 Alfa 地圖。",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "戰鬥中不顯示遊戲世界中角色與生物的滑鼠提示（框架上的仍會顯示）。",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "戰鬥中無法測試：脫離戰鬥後再回到這一步。",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "戰鬥中，圖示會顯示 Blizzard 戰鬥輔助建議的技能，以及接下來的 %d 個。按什麼由你決定：Alfa 絕不會替你按任何鍵。",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "戰鬥中，圖示會顯示 Blizzard 戰鬥輔助建議的技能。按什麼由你決定：Alfa 絕不會替你按任何鍵。",
	["En combate: espera a terminar"] = "戰鬥中：請等戰鬥結束",
	["En curso"] = "進行中",
	["En el camino"] = "順路",
	["En el chat"] = "在聊天視窗",
	["En el juego"] = "在遊戲中",
	["En el mapa"] = "在地圖上",
	["En el mapa del mundo"] = "在世界地圖上",
	["En el marco del objetivo"] = "目標框架",
	["En el minimapa"] = "在小地圖上",
	["En el mundo"] = "野外",
	["En el nivel 10 domas tu bestia."] = "10 級時可以馴服你的野獸。",
	["En el nivel 20 aprendes venenos."] = "20 級時學會毒藥。",
	["En esta zona"] = "在此地區",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "組隊時幾乎總是有好幾個敵人：你一次打兩個。",
	["En grupo, cura al tanque antes que a nadie."] = "組隊時，優先治療坦克。",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "組隊時，先治療坦克，也不要自己去拉怪。",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "組隊時，在生命值掉太多之前就治療：比較省法力。",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "組隊時，把法力與治療圖騰放在隊伍附近。",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "船艙洞穴裡有很多海盜：不要全部一起跳下碼頭。",
	["En la pelea, el juego te avisa"] = "戰鬥中，遊戲會提醒你",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "第二階段先殺她：她的治療量很大。",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "拍賣以看到的最低價格計算，並扣除手續費（%d%%，估計值）。分解則使用經典版遊戲的資料表，同樣是估計值。",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "在視窗與這裡顯示。如果你不在其中，你的那一列會顯示在最後。",
	["En las dos armas"] = "兩把武器都有",
	["En los mapas"] = "在地圖上",
	["En lugar de las del juego"] = "取代遊戲背包",
	["En marcha"] = "進行中",
	["En marcha hacia %s"] = "正在前往%s",
	["En mazmorra"] = "在地城中",
	["En mazmorras y bandas"] = "在地城與團隊副本中",
	["En mi zona"] = "在我的地區",
	["En otra zona: %s"] = "在其他地區：%s",
	["En pantalla"] = "顯示中",
	["En pausa"] = "已暫停",
	["En pausa dentro de la instancia"] = "副本中暫停",
	["En pausa por ahora"] = "暫時暫停",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "在旅店和城鎮中會累積休息經驗：擊殺敵人可獲得雙倍經驗值，直到用完為止。在這裡登出也會累積。",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "在旅店與城市中會累積休息經驗：每個敵人獲得雙倍經驗，直到用完。",
	["En qué orden aparecen."] = "顯示的順序。",
	["En solitario es lento: usa la varita para rematar."] = "單練時殺怪較慢：用魔杖收尾。",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "單練時，先上持續治療，再用憤怒術戰鬥。",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "單練時，用震擊戰鬥，並在兩隻怪之間治療自己。",
	["En su ficha toca «Agregar a mi ruta»."] = "在它的詳細頁面點擊「加入我的路線」。",
	["En tu arma"] = "武器上已有",
	["En tu marco"] = "你的框架",
	["En tu plan"] = "在你的計畫中",
	["En tu registro"] = "在你的任務日誌中",
	["En tus bolsas"] = "在你的背包裡",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "在背包、戰利品、聊天或任何連結中：Alt+點擊可開啟取得它的指南；如果沒有，則開啟它在百科中的詳細頁面。",
	["En un aviso"] = "以提醒顯示",
	["En un aviso y en el chat"] = "以提醒顯示並發到聊天視窗",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "搭乘有中途站的航線時，計時器下方會顯示下一站在哪裡、還要多久抵達。需要開啟飛行計時器。",
	["En una instancia: la flecha vuelve al salir"] = "在副本中：離開後箭頭就會回來",
	["En una pestaña nueva"] = "在新分頁中",
	["En unos segundos aparece tu build."] = "幾秒後就會顯示你的配點。",
	["En uso"] = "使用中",
	["En uso, a tu gusto"] = "使用中，依你的喜好",
	["En vivo"] = "即時",
	["En vivo si estás con un banquero; si no, la última foto."] = "在銀行職員旁時即時顯示；否則顯示最新快照。",
	["En vuelo: la flecha sigue al bajar"] = "飛行中：降落後箭頭會繼續",
	["En vuelo: la flecha sigue al bajar."] = "飛行中：降落後箭頭會繼續指引。",
	["Enanos"] = "矮人",
	["Encanta tu arma antes de pelear."] = "戰鬥前為武器附魔。",
	["Encantada"] = "已附魔",
	["Encantamiento"] = "附魔",
	["Encender el registro"] = "開啟記錄",
	["Encender la pesca"] = "開啟釣魚",
	["Encender las recomendadas"] = "開啟推薦項目",
	["Encenderla"] = "開啟",
	["Encenderlos"] = "開啟",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "開啟：即使被篩選條件排除也會加入計畫。關閉：不加入。",
	["Encendido"] = "已開啟",
	["Encendido y tecla"] = "開關與按鍵",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "開啟：釣魚時雙擊會再次拋竿，按住 Shift、Ctrl 或 Alt 雙擊則收竿。關閉：兩者相反。",
	["Enciclopedia"] = "百科",
	["Enciende las comodidades recomendadas"] = "開啟推薦的便利功能",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "對滑鼠移到角色或生物上時出現的提示，啟用下方的各項調整。",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "在試衣間（Ctrl+點擊物品）啟用下方的各項調整。",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "啟用下方的各項調整，每一項都可以單獨關閉。部分插件會在 /reload 後才把按鈕對齊方形小地圖。",
	["Enciende primero la guía en el minimapa."] = "請先開啟「小地圖上的指南」。",
	["Enciende primero los servicios."] = "請先開啟「服務」。",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "開啟後，戰鬥中會在一個可移動的小圖示裡顯示現在該用哪個技能以及接下來用哪些。",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "在下方「框架」中開啟，就能看到隊友的生命值並一鍵治療。",
	["Enciéndelos en la página Curación."] = "請在「治療」頁面開啟。",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "開啟後可查看隊伍的生命值，並一鍵治療。",
	["Enemigo raro"] = "稀有敵人",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "定住怪物並拉開距離，再施放施法時間長的法術。",
	["Entendido"] = "了解",
	["Entereza"] = "真言術：韌",
	["Entra al juego con él una vez."] = "用它登入遊戲一次。",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "帶著整潔的任務日誌進去：先交付你已有的任務。",
	["Entrada"] = "入口",
	["Entrada enemiga"] = "敵方入口",
	["Entradas de mazmorras"] = "地城入口",
	["Entradas en el minimapa"] = "小地圖上的入口",
	["Entraste a %s"] = "你進入了%s",
	["Entraste a %s."] = "你進入了%s。",
	["Entrega tus %d misiones listas"] = "交付你已完成的 %d 個任務",
	["Entregar"] = "交付",
	["Entregar las completadas"] = "交付已完成的任務",
	["Entregar mis misiones"] = "交付我的任務",
	["Entregar misiones"] = "交付任務",
	["Entregar solas las misiones de la guía"] = "自動交付指南中的任務",
	["Entregarlas ahora"] = "現在交付",
	["Entrenador"] = "訓練師",
	["Entrenador al día"] = "訓練已是最新",
	["Entrenador: %s, en %s."] = "訓練師：%s，位於%s。",
	["Entrenador: %s."] = "訓練師：%s。",
	["Entrégala a %s."] = "交給%s。",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "他會施毒並施放閃電：能解毒的話就解毒。",
	["Equilibrada"] = "均衡",
	["Equilibrado"] = "均衡",
	["Equilibrio"] = "平衡",
	["Equilibrio para subir"] = "平衡（練等）",
	["Equipa tu caña de pescar"] = "裝備你的魚竿",
	["Equipo"] = "裝備",
	["Equipo %d %%"] = "裝備 %d %%",
	["Equipo a punto de romperse."] = "裝備快要損壞了。",
	["Equipo y estadísticas"] = "裝備與屬性",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "裝備、消耗品、任務物品、材料……標題可摺疊。",
	["Eres de la manada"] = "你是狼群的一員",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "你是 %d 級，建議 %d 級：從那裡開始這樣計算。",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "這個地城很短，位於暴風城內。囚犯關在兩側的牢房裡：慢慢推進。",
	["Es de la otra facción"] = "屬於另一陣營",
	["Es de una misión."] = "這是任務物品。",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "聯盟有任務需要擊敗這個首領：進去前先檢查你的任務。",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "第一個首領，很簡單。他死後，你陣營的囚犯會打開通往庭院的門。",
	["Es el punto %d de %d de tu build."] = "這是你配點的第 %d/%d 點。",
	["Es el que toca ahora."] = "現在該點這個。",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "墓地的最後一個首領。他會在周圍釋放火焰：遠程職業請保持距離。",
	["Es el único lobo a la vista."] = "視野中只有這一隻狼。",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "這裡很大，很容易迷路：跟著同一個人走，不要自己亂跑。",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "這是斯尼德的機器：把它打壞，他就會出來戰鬥。",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "部落的第一個地城：很短，適合學習團隊合作。",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "聯盟的第一個大型地城：慢慢推進，一次拉一群怪。",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "這個地城很長，有兩個入口。很多敵人是石頭做的，攻擊很痛。",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "這個地城很長，有很多機器人：有些會放炸彈，或拉響警報引來更多敵人。",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "他動作很慢：遠程職業可以趁他靠近時攻擊。",
	["Es muy veloz: frénalo si tu clase puede."] = "他速度很快：你的職業能減速的話就減速他。",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "適合 %s 級，你是 %d 級：還差 %d 級。",
	["Es para otra raza."] = "適用於其他種族。",
	["Es raro del Cementerio y no siempre aparece."] = "墓地的稀有首領，不一定會出現。",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "墓地的稀有首領，不一定會出現。會施毒：記得解毒。",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "墓地的稀有首領，不一定會出現。會沉默施法者。",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "稀有首領，很少出現。會在周圍施放火焰。",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "稀有首領，位於隱藏的洞穴中。是一隻攻擊很快的蝙蝠。",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "稀有首領，不一定會出現。以他的等級來說攻擊非常痛：拉怪時要小心。",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "稀有首領，不一定會出現。會重擊面前所有人。",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "稀有首領。會放置大地圖騰：把它打掉。",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "稀有首領：不一定會出現。會催眠玩家，並在周圍引發魔法爆炸。",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "這個很簡單：是在最後一個首領前喝水回魔的好時機。",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "他是施法者：你的職業能打斷的話就打斷他（腳踢、盾擊、地震術...）。",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "他是會放圖騰的薩滿：把圖騰打掉，很容易打死。",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "一個拿盾牌的矮人：很耐打，但沒有特別的技巧。",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "礦坑裡的強敵：把他當成小首領來打。",
	["Es un grupo: cada uno suelta su propio botín."] = "這是一組敵人：每個都會掉落自己的戰利品。",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "他是聖騎士，會用聖光術治療自己。打斷他的治療。",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "一個速度很快、會施毒的薩特：你的職業能解毒的話就解毒。",
	["Es un trogg que lanza rayos: interrúmpelo."] = "一個會施放閃電的穴居人：打斷他。",
	["Es una mejora para ti"] = "對你是提升",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "一隻護甲很厚的巨大烏龜：攻擊慢但很痛。",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "一隻非常耐打的烏龜，但只會普通攻擊：沒有特別的技巧。",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "該字串中沒有 Alfa 會計分的屬性。",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "那一排還沒解鎖：該系的點數不夠。",
	["Esa tecla ya tiene dueño"] = "這個按鍵已被佔用",
	["Escala de estadísticas"] = "屬性權重",
	["Escalas:"] = "中途站：",
	["Escaneando..."] = "掃描中...",
	["Escanear ahora"] = "立即掃描",
	["Escanear con Alfa"] = "用 Alfa 掃描",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "完整掃描：%s 件物品有價格（%s 筆拍賣）。",
	["Escarcha"] = "冰霜",
	["Escarcha para subir"] = "冰霜（練等）",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "釣魚時隱藏名條與 NPC 名稱（敵對目標仍會顯示名稱），讓浮標更容易看到、也更好點擊。",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "隱藏需要比你目前更高技能的採集點。關閉時會以灰色淡化顯示。",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "輸入 %s 或點擊小地圖上的狼即可開啟。視窗會先顯示「今天」，列出你的職業需要的東西；%s 可顯示或隱藏指南視窗。",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "輸入 %s，然後在 La Jauría 的 Discord 告訴我們。",
