	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "此用戶端無法自動複製你的點擊配置：已開啟 Blizzard 的點擊施法視窗，讓你在那裡設定。",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "此用戶端沒有 Blizzard 的點擊施法。你的點擊配置在 Alfa 的框架上有效。",
	["Este paso no tiene punto en el mapa."] = "這個步驟在地圖上沒有位置。",
