	["Estilo y sonido"] = "風格與音效",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "戰鬥中無法變更。請在戰鬥結束後再試。",
	["Esto no se puede vincular."] = "這個無法連結。",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "他在墓地。會施放持續造成傷害的暗影痛苦。",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "他在瀑布旁的水中：先把他拉到陸地上再打。",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "他在軍械庫。他大吼時會揮斧旋轉，打到附近所有人：快離開。",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "他在圖書館，會帶著獵犬：先殺獵犬，或使用範圍攻擊。",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "他藏在大教堂裡。會施放詛咒並治療自己：打斷他。",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "這裡滿是野豬人和荊棘隧道：一次只拉少量的怪。",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "他周圍有正在工作的地精：先一個一個把那些地精拉走。",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "他被魚人包圍：先拉他的同伴，再打他。",
	["Estás aquí"] = "你在這裡",
