	["Estás dentro"] = "你在裡面",
	["Estás descansando"] = "你正在休息",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "你正在戰鬥中。天賦只能在戰鬥外變更：請打完再試一次。",
	["Estás en combate: busca el equipo al terminar la pelea."] = "你正在戰鬥中：請在戰鬥結束後再搜尋裝備。",
