	["Intelecto"] = "智力",
	["Intelecto Arcano"] = "秘法智慧",
	["Intentar ahora"] = "立即重試",
	["Intentar otra vez"] = "重試",
	["Interceptar más seguido: el rival no se escapa."] = "更常使用攔截：對手跑不掉。",
	["Interrumpes hechizos y los silencias."] = "打斷法術並使其沉默。",
	["Interrumpes y silencias hechizos."] = "打斷並沉默法術。",
	["Invitar"] = "邀請",
	["Invitar al grupo"] = "邀請組隊",
	["Invitar, comerciar, susurrar…"] = "邀請、交易、密語…",
	["Invitaste a %s a tu grupo."] = "你邀請了 %s 加入隊伍。",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "他會召喚野豬之靈：把它殺掉，或讓人去坦它。",
	["Invócalo antes de pelear."] = "戰鬥前先召喚它。",
	["Ir"] = "前往",
	["Ir al mapa del juego"] = "前往遊戲地圖",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "解除恐懼時獲得怒氣：對手很常恐懼你。",
	["Ira aunque el rival huya o te frene."] = "即使對手逃跑或讓你減速，也能獲得怒氣。",
	["Ira constante en peleas largas contra jefes."] = "在漫長的首領戰中穩定獲得怒氣。",
	["Ira constante."] = "穩定獲得怒氣。",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "穩定獲得怒氣：永遠不會沒技能可用。",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "每隔幾秒免費獲得怒氣，即使沒人打你。",
	["Izquierdo"] = "左鍵",
	["JcJ"] = "PvP",
	["Jefe"] = "首領",
	["Jefe %d por descubrir"] = "首領 %d（尚未發現）",
	["Jefe final"] = "最終首領",
	["Jefes"] = "首領",
	["Jefes vencidos"] = "已擊敗的首領",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "此角色已擊敗的首領、完成的地城與記錄的戰利品。不會影響你的設定。",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "每個地城與團隊副本的首領、戰利品與入口。",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "每個角色玩一次，Alfa 就會記住它的背包與銀行。",
	["Juega siempre en actitud defensiva con escudo."] = "一律在防禦姿態下持盾作戰。",
	["Junta %d de %s"] = "採集 %d 個%s",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "一次拉兩隻怪並使用橫掃攻擊：這樣升級更快。",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "一次拉兩三隻怪，使用雷霆一擊與復仇：升級又安全又不用休息。",
	["Junta los montones y acomoda tus objetos con un clic."] = "點一下就能合併堆疊並整理物品。",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "合併堆疊並整理物品。戰鬥中無法使用。",
	["Junta materiales de tu profesión donde más hay."] = "到最多的地方採集你的專業材料。",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "採集你的專業材料，中間穿插一些經驗值任務。",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "一次拉好幾隻怪：你的神聖攻擊會打到每一隻。",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "正在彙整遊戲中的所有內容。只有第一次開啟時需要。",
	["Juntar los materiales de mi profesión"] = "收集我專業所需的材料",
	["Juntar materiales para vender"] = "收集材料出售",
	["Juntar nodos cercanos al alejar"] = "縮小地圖時合併相近的採集點",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "在遊戲地圖的放大鏡旁：圖層、簡潔模式，以及切換到 Alfa 地圖的「Alfa 地圖」按鈕。",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "按 B、Shift+B、各背包的按鍵或與商人交談時會開啟 Alfa 的視窗。關閉此選項即可改回遊戲背包。",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "地圖上的 La Jauría",
	["La Jauría son todos los que usan Alfa. Si aceptas, quienes también comparten te ven en su mapa y te pueden seguir con la flecha, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase, nunca dentro de mazmorras. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "La Jauría 就是所有使用 Alfa 的人。如果你同意，同樣分享位置的人能在地圖上看到你，並能用箭頭跟隨你，你也能看到他們。傳送的內容是你的地區、位置、等級與職業，在地城內絕不傳送。你的隊伍一律看得到。隨時可在 La Jauría 中變更。",
	["La Jauría son todos los que usan Alfa. Si compartes tu ubicación, te ven en su mapa y tú a ellos: quién anda cerca, dónde y, con un clic, la flecha te lleva. Tu grupo se ve siempre, compartas o no."] = "La Jauría 就是所有使用 Alfa 的人。如果你分享位置，他們能在地圖上看到你，你也能看到他們：誰在附近、在哪裡，點一下箭頭就會帶你過去。無論是否分享，你的隊伍一律看得到。",
	["La Jauría te ve"] = "La Jauría 看得到你",
	["La Jauría: estado"] = "La Jauría：狀態",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría：地圖上的狼群、跟隨功能與公會（/alfa manada ayuda）",
	["La Jauría: tus comandos"] = "La Jauría：你的指令",
	["La ayuda de rotación está apagada"] = "輸出循環助手已關閉",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "生命條使用每個人的職業顏色。關閉時：生命條為綠色，名字使用職業顏色。",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "內建資料庫有 %s 個位置，分布在 %d 個地區。你發現了 %s 個。",
	["La bienvenida con las novedades de esta versión."] = "包含此版本新功能的歡迎頁面。",
	["La búsqueda de lugares cercanos no está disponible."] = "無法使用附近地點搜尋。",
	["La cadena no trae talentos válidos."] = "這段字串中沒有有效的天賦。",
	["La cura de ese clic pasa al botón central."] = "該點擊的治療會移到中鍵。",
	["La derecha"] = "向右",
	["La empieza un objeto"] = "由物品開始",
	["La enciclopedia de La Jauría"] = "La Jauría 百科",
	["La enciclopedia no puede abrir todavía"] = "百科暫時無法開啟",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "在小地圖上顯示每個地城的入口，已完成的會以綠色顯示。世界地圖已經用「地城入口」標記了它們。",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "箭頭會隨著對方的蹤跡移動，抵達後停止。",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "箭頭會依 Alfa 的步行地圖，沿地面繞過懸崖、水域與牆壁前進。關閉：直接指向每一站。",
	["La flecha sigue en el paso de ahora."] = "箭頭仍指向目前步驟。",
	["La flecha te lleva a %s."] = "箭頭會帶你去%s。",
	["La flecha te lleva aquí."] = "箭頭會帶你到這裡。",
	["La flecha te lleva de un lugar al siguiente."] = "箭頭會帶你從一個地點到下一個地點。",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "箭頭已改指向其他目的地：你已停止跟隨 %s。",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "箭頭會在划算時使用飛行與爐石。",
	["La flecha ya no sigue tu ruta de farmeo."] = "箭頭已不再跟隨你的採集路線。",
	["La guía en el minimapa"] = "小地圖上的指南",
	["La guía que mejor te queda por tu nivel y donde estás."] = "依你的等級與所在位置最適合你的指南。",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "你正在跟隨的指南、目前的步驟，以及一鍵可及的所有指南功能。",
	["La guía te lleva a entrenar en %d pasos."] = "指南會在 %d 個步驟後帶你去訓練。",
	["La guía te lleva a quien recibe cada una."] = "指南會帶你去找每個任務的交付人。",
	["La haces de paso: abre %s."] = "順路完成：它會開啟%s。",
	["La haré"] = "我會做",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "皮膚的字型（Alfa 皮膚用 Inter，光環用 Fira Sans，其他皮膚用遊戲字型），或你選擇的字型。",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "清單已關閉：請在便利功能（/alfa comodidades）中開啟「你的聲音清單」。",
	["La lista por nivel y tu progreso."] = "依等級排列的清單與你的進度。",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Blizzard 的時間軸會顯示接下來是什麼攻擊、何時到來，大字訊息會告訴你危險所在。Alfa 不會自創警報：你可以在設定中開啟與調整。",
	["La línea del camino también en el minimapa."] = "也在小地圖上顯示路徑線。",
	["La manada a la vista"] = "視野中的狼群",
	["La manada aúlla contigo."] = "狼群與你一起嚎叫。",
	["La manada te saluda al abrir Alfa por primera vez en la sesión."] = "每次登入後第一次開啟 Alfa 時，狼群會向你打招呼。",
	["La mazmorra para mi nivel"] = "適合我等級的地城",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "適合你等級的地城，以及它的首領、戰利品、任務與提示。",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "適合你等級的地城、它的任務以及如何前往。",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "適合你等級的地城；加上名稱則顯示該地城（也可用：progreso、ajustes）",
	["La pesca de Alfa está apagada"] = "Alfa 釣魚功能已關閉",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "命中最重要：用雙武器時沒有它會常常打不中。",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "背包頁面；加上「abrir」開啟背包，加上「banco」開啟銀行",
	["La que te toca, con sus misiones y su botín."] = "適合你的那個，附帶任務與戰利品。",
	["La recoges ahora"] = "現在接取",
	["La recomendada para ti y todas las demás"] = "為你推薦的以及其他所有",
	["La recomendada para ti y todas las demás."] = "為你推薦的以及其他所有。",
	["La ruta más rápida desde tu nivel, misión por misión."] = "從你的等級出發的最快路線，一個任務接一個任務。",
	["La ruta no trae tramos."] = "這條路線沒有任何路段。",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "路線會帶你去%s。箭頭已關閉：請在「設定 > 指南」中開啟才能看到。",
	["La sacas de tu plan."] = "你把它從計畫中移除。",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "下一個欄位需要 %s，你的錢還不夠。",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "拍賣場每 15 分鐘才能完整掃描一次。還要 %s。",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "拍賣場不接受這次掃描。請稍後再試。",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "拍賣場沒有傳回任何拍賣。請稍後再試。",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "拍賣場沒有回應。可能還在冷卻中：請過幾分鐘再試。",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Alfa 為每個角色儲存的總和（你目前的角色為即時資料）。",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "圖示上顯示快捷列中該技能按鈕的按鍵。",
	["La tecla del mapa abre este mapa"] = "地圖鍵開啟此地圖",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "開啟遊戲地圖的按鍵（M）會開啟 Alfa 地圖；其中有一個按鈕可前往遊戲地圖。關閉此選項，按鍵會恢復開啟遊戲地圖。你也可以在「選項 > 按鍵設定 > Alfa」中為它設定專屬按鍵。",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "你在其他釣魚插件使用的按鍵（%s）現在改用 Alfa 釣魚。",
	["La tomo otra vez"] = "我再接一次",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "伐木機會把人擊退：盡快把仇恨拉回來。",
	["La tuya tiene %d semanas: salen seguido."] = "你的版本已有 %d 週：更新很頻繁。",
	["La venta se detuvo: vendiste %d de %d."] = "出售已停止：你賣出了 %d/%d 件。",
	["La ventana"] = "視窗",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "他會施放火球術並在周圍釋放火焰：打斷他，遠程職業請保持距離。",
	["Lanza bombas de humo que aturden: sal del humo."] = "他會丟出會擊昏人的煙霧彈：離開煙霧。",
	["Lanza con una tecla y recoge con la misma, con autobotín, sonido amplificado y doble clic."] = "用同一個按鍵拋竿與收竿，支援自動拾取、增強音效與雙擊。",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "他會施放藤蔓，擊倒附近所有人：遠程職業請保持距離。",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "他會在周圍釋放火焰：遠程職業請離他遠一點。",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "他會施放大地法術並放置圖騰：先把圖騰打掉。",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "他會潑灑熔化的金屬：如果你不是坦克，不要貼在他身邊。",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "她會施放閃電，也會治療自己：打斷她的法術。",
	["Lanza ráfagas arcanas: interrúmpelo."] = "他會施放秘法衝擊：打斷他。",
	["Lanza sombras: interrúmpelo."] = "他會施放暗影法術：打斷他。",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "他會吐蛛網並施放詛咒：能解除詛咒的話就解除。",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "他會製造在房間內移動的沙暴：不要站在裡面。",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "從遠處施放你最強的法術，再用瞬發法術收尾。",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "先施放你最強的法術，再用震擊收尾。",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "她會向前噴出毒雲：把她轉向背對隊伍。",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "他會丟出網子定住一名玩家：不要緊，繼續攻擊。",
	["Lanza veneno a todos: quita el veneno si puedes."] = "他會對所有人施毒：能解毒的話就解毒。",
	["Las cuentas"] = "計算明細",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "試玩帳號無法分享：遊戲不允許。",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "這兩個專業會在你殺怪與旅行時自然提升，採到的東西也很好賣：賺錢買坐騎與學技能。",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "「通報」在你的隊伍或團隊聊天中發布的內容。",
	["Las marca con una flecha."] = "會用箭頭標出提升。",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "狼群的標記也顯示在小地圖上，而不只是世界地圖。",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "你附近現在就能接的最佳任務，依最短順序。",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "前置任務與所需等級，讓你能接取它。",
	["Las misiones que más experiencia dan cerca de ti."] = "你附近經驗值最多的任務。",
