	["Llega con guardias: tírenlos aparte si pueden."] = "他會帶著守衛：可以的話把守衛分開拉。",
	["Llega con lobos: elimínenlos primero."] = "他會帶著狼：先把狼解決掉。",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "他會帶著他的狗：每隻各由一個人坦，或是先殺狗。",
	["Llega en el nivel %d"] = "%d 級時取得",
	["Llegas al rival con ira para pegar de inmediato."] = "衝到對手面前時就有怒氣，可以立刻開打。",
