	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "把鏡頭距離（選項 > 控制中的設定）調到最大。關閉後會恢復你原本的設定。",
	["Lleva siempre un sello puesto aunque estés curando."] = "即使在治療時，也要一直保持一個聖印。",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "隨身帶著繃帶與食物：稍微休息、安全地打，比死掉還快。",
	["Llevas %d de %d pasos. El rastreador te dice el siguiente y la flecha te lleva."] = "已完成 %d/%d 步。追蹤器會告訴你下一步，箭頭會帶你過去。",
