	["Lo estás siguiendo."] = "你正在跟隨對方。",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "灰色物品與你標記為垃圾的物品。絕不包括你標記為保留或任務需要的物品。",
