	["Lo nuevo y tu Alfa a tu medida"] = "新功能，以及專屬於你的 Alfa",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, marcos, cuadro de información, probador, cámara y sonidos."] = "讓遊戲更舒適的小功能：任務、飛行、小地圖、框架、滑鼠提示、試衣間、鏡頭與音效。",
	["Lo pescado en esta sesión"] = "本次的漁獲",
	["Lo piden estas misiones"] = "需要它的任務",
	["Lo pones al empezar a pelear."] = "戰鬥開始時施放。",
	["Lo que buscas en la Enciclopedia"] = "你在百科中查詢的內容",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "隊伍中有人用 Alfa 分享的內容會進入你的標記，附帶其名稱，並提醒你跟隨。",
	["Lo que conoce Alfa"] = "Alfa 已知的",
	["Lo que da"] = "提供的東西",
	["Lo que encuentras en la manada"] = "在狼群中你會找到什麼",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "此角色在地城中的進度：擊敗首領與拾取戰利品時自動儲存。",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "你上次用這個角色遊玩時的收穫。",
