	["Lo que obtuviste en esta sesión"] = "本次獲得的東西",
	["Lo que pide %s antes, en orden."] = "%s的前置條件，依順序。",
	["Lo que saques aparece aquí, con cuántos llevas de cada uno."] = "你釣到的東西會顯示在這裡，以及每種的數量。",
	["Lo que se pesca aquí"] = "這裡能釣到的",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "拍賣場從每筆成交中抽取的部分。通常陣營拍賣場為 5%，中立拍賣場為 15%。這是估計值。",
	["Lo que sigue en tu build no está en tu árbol"] = "你配點接下來的部分不在你的天賦樹中",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "接下來的內容需要這個等級：在那之前，指南不會讓你過去。",
	["Lo que sugiere Alfa"] = "Alfa 的建議",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "你的配點對裝備的需求，以及在哪裡取得。",
	["Lo que tu clase se pone antes de pelear está activo."] = "你的職業戰鬥前要上的增益已生效。",
	["Lo que tu profesión de recolección junta mejor."] = "你的採集專業最擅長採集的東西。",
