	["Lo último que consultaste"] = "最近查詢的內容",
	["Lobo"] = "狼",
	["Lobos conectados"] = "線上狼群",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPC 跟你打招呼或給你任務時不再說話。也會關閉錯誤語音。",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "提醒的設定可以在 Alfa 視窗的搜尋中找到。",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "小地圖周圍其他插件的按鈕（包括 Alfa 的）只在滑鼠移到上面時才出現。",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "血色十字軍成群出現，有些會治療：打斷會治療的。",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "致命一擊造成雙倍傷害，還會讓戰士獲得更多怒氣。",
	["Los datos de Alfa no cargaron (%s)."] = "Alfa 的資料沒有載入（%s）。",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Alfa 的資料中沒有它的首領專屬戰利品。",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "地城資料會在脫離戰鬥後載入。戰鬥結束後此頁面會自動填滿。",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "資料來自遊戲官方的傷害統計：你、你的隊伍或團隊以及他們的寵物。",
	["Los enemigos de alrededor pegan menos."] = "周圍的敵人造成的傷害降低。",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "敵人會施放輻射與毒素：記得帶治療藥水。",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "地卜師會施放火焰並放置圖騰：打斷他們並打掉圖騰。",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "鑄造廠的地精附近有幫手：攻擊前先看看四周。",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "選擇性首領與稀有首領會在完成地城後揭曉。",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "首領要擊敗後才會揭曉：在那之前其名稱與戰利品都會隱藏。提示則隨時都能查看。",
	["Los lobos que usan Alfa y comparten su ubicación, y tu grupo, que ves ahora."] = "使用 Alfa 並分享位置的狼，以及你現在能看到的隊伍成員。",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "你從百科中要求在地圖上顯示的地點。",
	["Los marcos de Curación están apagados"] = "治療框架已關閉",
	["Los marcos se mueven fuera de combate."] = "框架只能在戰鬥外移動。",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "遊戲內建的框架、背景、按鈕與字型，標題為金色。",
	["Los mismos marcadores de misiones en el minimapa."] = "在小地圖上顯示相同的任務標記。",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "納迦和薩特會施放冰霜與閃電：先打斷施法者。",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "你正在查看的地區中的採集點；滑鼠移到上面可查看名稱、等級與你採集過的次數。點擊一個：箭頭會帶你過去。",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "在畫面上會重疊的採集點會合併成一個標記並顯示數量。放大地圖時就會分開。",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "你附近的採集點。遊戲的追蹤點會告訴你現在那裡有沒有東西。",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Alfa 內建的採集點。關閉時只會看到你自己發現的。",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "物品會集中在背包的最後面，而不是最前面。",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "規劃中其他 %d 點會在你接下來升級時取得。",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "價格會變動：超過這些天數後，Alfa 會提醒你重新掃描。",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "其他插件設定的路徑點以及 /way 指令會由 Alfa 的箭頭指引。開啟後，需要其他路徑點插件自身設定的插件可能無法正常運作。",
	["Los raros están apagados (página Descubrir)."] = "稀有怪已關閉（「探索」頁面）。",
	["Los raros también en el minimapa."] = "也在小地圖上顯示稀有怪。",
	["Los recolectaste %d veces en total"] = "你總共採集過 %d 次",
	["Los servicios también en el minimapa."] = "也在小地圖上顯示服務。",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "確認後的天賦無法免費重置：接受前請先檢查清單。",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "配點中接下來的天賦不在你的天賦樹中，或暫時無法點。請在遊戲的天賦視窗中手動點，或選擇其他配點。",
	["Los tesoros también en el minimapa."] = "也在小地圖上顯示寶藏。",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "穴居人生命值低時會逃跑並找來同伴：在他們逃走前攔住他們。",
	["Los últimos puntos."] = "最後的點數。",
