	["Otro addon de pesca está activo. Para que no choquen, la pesca de Alfa queda en pausa: desactiva uno de los dos en la lista de addons."] = "另一個釣魚插件已啟用。為避免衝突，Alfa 的釣魚功能已暫停：請在插件清單中停用其中一個。",
	["Otro golpe fuerte para tu rotación."] = "為你的輸出循環增加另一個強力攻擊。",
