	["Panel de estadísticas"] = "屬性面板",
	["Para abandonar"] = "要放棄的任務",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "要用地圖鍵開啟它，請開啟下方的「用地圖鍵開啟 Alfa 地圖」。",
	["Para alguien de tu hermandad, agrega su rango."] = "對你的公會成員，加上他的公會階級。",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Alfa 會為每件物品比較三種做法：賣給商人、拿去拍賣，或加工成其他東西（用你會的配方或將它分解）。",
	["Para comprar espacio, habla con un banquero."] = "要購買空間，請與銀行職員交談。",
	["Para conservar"] = "要保留的",
	["Para depositar, habla con un banquero."] = "要存放，請與銀行職員交談。",
	["Para empezar"] = "如何開始",
	["Para entregar"] = "待交付",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "你選的組合沒有這種風格的配點：Alfa 會使用最接近的。",
	["Para mi nivel (±3)"] = "適合我的等級（±3）",
	["Para mí"] = "適合我",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "為避免衝突，它啟用期間 Alfa 不會取代你的背包。你仍然可以從這裡開啟 Alfa 的視窗。",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "避免隊伍重複顯示。只能在戰鬥外變更。",
	["Para pescar necesitas una caña en las manos. Cuando la tengas puesta, ya puedes lanzar."] = "釣魚需要手持魚竿。裝備好之後就可以拋竿了。",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "為避免衝突，Alfa 不會接管你的按鍵，也不會更改你的設定。請在插件清單（角色選擇畫面）中停用其中一個並重新載入。如果保留 Alfa，它會自動沿用你在其他插件用的按鍵。",
	["Para que no dejes botín tirado por falta de espacio."] = "以免因為空間不足而撿不了戰利品。",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "適合喜歡用左鍵選取目標的人：原本左鍵的治療會移到中鍵。並會重新套用你的預設方案。",
	["Para recoger ahora"] = "現在可接取",
