	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "你招架了一次攻擊：你的反擊已就緒，還會繳械敵人。",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "你招架了一次攻擊：你的反擊會讓敵人無法移動。",
