	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "將滑鼠移到隊友身上並點擊：左鍵%s，右鍵%s。",
	["Pasa enfermedades: quítalas si tu clase puede."] = "他會散播疾病：你的職業能驅散的話就驅散。",
	["Pasa tu build a un amigo o usa el que te pasen."] = "把你的配點分享給朋友，或使用別人分享的配點。",
