	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "兩次點擊之間的最長間隔。如果雙擊無法拋竿，請調高此值。",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "這裡分成四個區域，要分開打：墓地、圖書館、軍械庫與大教堂，由易到難。",
