	["Tienes %d puntos de talento: empieza por %s"] = "你有 %d 點天賦點數：先點%s",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "你有 %d 點不在%s中。Alfa 絕不會移除天賦：要跟隨這個配點，請找職業訓練師重置天賦，Alfa 會一鍵幫你重新點好。或者選擇你已點的天賦系的配點。",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "你有 %d 點未分配點數，但%s中接下來的天賦在你的天賦樹中不存在（可能被修正檔改動了）。請在遊戲視窗中手動點，或試試其他風格。",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "你有 %s 個來自搜尋的價格。想知道全部的價格，請在拍賣場掃描。",
	["Tienes 1 misión lista para entregar"] = "你有 1 個任務可交付",
