	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "每次登入後第一次開啟 Alfa 時，播放一聲遊戲內建的狼嚎。",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "一則提醒，顯示它的首領與你已擊敗的數量，點一下即可查看提示。",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "當依賴剛才情況的技能被觸發時（例如敵人閃躲後的壓制），顯示簡短提醒。",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "擊敗新首領時的提醒，點一下即可查看它的戰利品。",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "一則提醒與背包中的一欄，告訴你該賣什麼、該留什麼、去找哪個商人，一鍵標記垃圾。",
	["Un borde del color de la calidad: verde, azul, morado..."] = "以品質顏色顯示邊框：綠色、藍色、紫色...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "在快捷列上帶有建議技能的按鈕周圍顯示閃動的綠色邊框，讓你快速找到。",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "點一下就只保留必要內容：你、你的隊伍、你的標記與指南的下一步。",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "一個可移動的小框，顯示你的生命值與對你職業最重要的屬性。戰鬥中遊戲會隱藏部分數字：會保留最後讀到的數值。",
	["Un enemigo"] = "單體",
	["Un fondo del color de tu clase bajo tu nombre."] = "在你的名字下方加上職業顏色的背景。",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "用盾牌打出超強一擊，並產生大量仇恨。",
	["Un golpe más para gastar ira."] = "多一個消耗怒氣的攻擊。",
	["Un golpe nuevo y fuerte para tu barra."] = "為你的快捷列添加一個新的強力攻擊。",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "對付難纏的怪物時大幅提升傷害；還能讓你免疫恐懼。",
	["Un hechizo de tus barras tiene un rango viejo"] = "你的快捷列上有一個法術是舊等級",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "任務需要的物品會有金色外框（能開始任務的物品會標上「!」）。",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "你想要的物品：Alfa 會規劃取得它的路線，包括所需的前置條件。",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "在接下來的步驟要去的地方放上附編號的小標記。",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "少量的致命一擊、閃躲與護甲。",
	["Un poco de vida de vuelta después de críticos."] = "致命一擊後回復少量生命值。",
	["Un poco más de defensa."] = "稍微多一點防禦。",
	["Un poco más de ira al cargar."] = "衝鋒時多一點怒氣。",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "點一點來解鎖下一排，也稍微減少失手。",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "在提供適合你等級任務的人頭上顯示驚嘆號。",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "在可繳交已完成任務的人頭上顯示問號。",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "一個插件包含遊戲中用到的一切：附箭頭與路線的逐步指南、地圖、背包、配點、點擊治療、採集、地城、釣魚與交易。風格一致。",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "打得很痛的坦克：為輸出很高的隊伍提供大量仇恨，代價是額外防禦較少。適合有一些經驗的坦克。",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "一個顯示現在最適合技能的圖示。只負責顯示：絕不會替你按任何鍵。",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "一個醒目的推薦動作，點幾下就能看到你的路線。",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "一條顯示首領即將施放的攻擊與倒數時間的長條，讓你知道何時該移動或防禦。",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "一段文字就能包含完整的配點：你複製、傳送，對方貼上即可。",
	["Una categoría…"] = "某個分類…",
	["Una cuenta de prueba no puede compartir"] = "試玩帳號無法分享",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "在背包中每件對你專精有提升的物品上顯示綠色箭頭。",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "依你的職業與等級，比身上裝備更好的裝備會顯示綠色箭頭。",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "淺綠色的長條顯示即將到達的治療量。",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "適合你等級與地區的指南，或你自己的任務路線。",
	["Una línea debajo del aviso con lo que pasó."] = "提醒下方一行說明剛才發生了什麼。",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "敵人鎖定該隊友時，上方會出現紅線提醒。",
	["Una mano"] = "單手",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "在灰色物品與你標記為垃圾的物品上顯示一枚硬幣。",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Empieza con una plantilla."] = "路線是由路段組成的樹：經驗、金幣或職業任務、材料或物品。從範本開始吧。",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "一條路線至少需要 3 個你的技能能採集的地點。請在下方選擇其他類型或資源，或在這裡採集：Alfa 會記錄你發現的每個採集點。",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "一條經過適合你技能的最佳地點的路線，中間穿插一些經驗任務。",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "把你的技能能採集的 %d 個地點連成一條短環線，畫在地圖上，箭頭會逐站帶你。",
	["Uno menos"] = "少一個",
	["Uno más"] = "多一個",
	["Usa %s"] = "使用%s",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "首領打得很痛時，使用盾牌格擋。",
	["Usa Deseo de muerte al empezar contra un jefe."] = "打首領時一開場就使用死亡之願。",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "對付難纏的怪物時才使用死亡之願，簡單的怪就不用。",
	["Usa Golpe mortal sobre todo contra sanadores."] = "優先對治療者使用致死打擊。",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "有兩個以上的敵人聚在一起時，使用橫掃攻擊。",
	["Usa Ira rabiosa para romper miedos."] = "用狂暴之怒解除恐懼。",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "每次復仇亮起時就使用，並用破甲攻擊累積仇恨。",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "使用生命分流，以生命值換取法力。",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "讓你的惡魔拖住怪物，你負責施法。",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "使用審判，然後立刻重新上聖印。",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "在建議技能的按鈕上使用遊戲內建的標示效果。",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "對付一隻怪時用獵豹形態，來了好幾隻就用熊形態。",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "用你的主力攻擊累積連擊點數，再用終結技消耗掉。",
	["Usa tu varita cuando quieras ahorrar maná."] = "想省法力時就用魔杖。",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "被兩隻怪圍住時，使用你的控場法術。",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "使用速度慢、威力強的武器：你的武器強化效果每一擊都會觸發。",
